// sglang's RMSNorm (aiter's rmsnorm2d) of M rows, each thread holding LOADS x 8 values of every row
// (rms_norm's layout, common/math.h): x = bf16(x rsqrt(sum(x^2) / N + eps) gamma), rounded once.
#pragma once

#include "common/math.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// LDS_ONLY: BlockReduce's
template <int NUM_TOKENS, int LOADS, bool LDS_ONLY>
__device__ __forceinline__ void rms_norm_sglang(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                                const bfloat16 (&gamma)[LOADS][8], float eps,
                                                float *reduce) {
    constexpr int N = LOADS * 8 * Config::BLOCK_SIZE;
    float         sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        sums[m] = sum2.x + sum2.y;
    }
    BlockReduce<SumOp, Config::BLOCK_SIZE, LDS_ONLY>(sums, reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const float factor = rsqrtf(sums[m] / N + eps);
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
#pragma unroll
            for (int j = 0; j < 8; ++j) {
                x[m][i][j] = static_cast<bfloat16>(static_cast<float>(x[m][i][j]) * factor *
                                                   static_cast<float>(gamma[i][j]));
            }
        }
    }
}

} // namespace infera_flash::glm5

// Device primitives: vector types, loads and stores with cache-policy bits, fp8 and MXFP4 MFMAs,
// wave and block reductions.
#pragma once

#include <hip/hip_runtime.h>

#include "common/hw.h"

namespace infera_flash {

using bfloat16 = __bf16; // not hip_bfloat16: it rounds in software, with a branch per value

using uint32x4 = uint32_t __attribute__((ext_vector_type(4)));
using int32x4  = int __attribute__((ext_vector_type(4)));
using int32x8  = int __attribute__((ext_vector_type(8)));
using floatx2  = float __attribute__((ext_vector_type(2)));
using floatx4  = float __attribute__((ext_vector_type(4)));

template <typename T, int N> __device__ inline void load_data(const T *src, T *dst) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

template <typename T, int N> __device__ inline void store_data(T *dst, const T *src) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

// sc1 sends a global access through the device-wide coherence point. Without it a store stays in
// this XCD's L2 and a load can keep hitting a stale L1 line, so other XCDs never see the value.
// s_nop 1: a VALU must not overwrite the store's data VGPRs for 2 wait states (ISA 4.5), and the
// compiler does not pad stores inside asm.
__device__ inline void store_sc1(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(uint2 *ptr, uint2 val) {
    asm volatile("global_store_dwordx2 %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(uint32_t *ptr, uint32_t val) {
    asm volatile("global_store_dword %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(bfloat16 *ptr, bfloat16 val) {
    const uint32_t bits = __builtin_bit_cast(uint16_t, val);
    asm volatile("global_store_short %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(bits) : "memory");
}

// 16 B packets between blocks of one XCD: the store reaches their L2, an nt load reads it there
// past the CU cache (CDNA4 ISA, tables 49 and 50). asm store, so it is not merged or moved.
__device__ inline void store_l2(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline uint32x4 buffer_load_l2(__amdgpu_buffer_rsrc_t buffer, int offset) {
    constexpr int NT = 2; // the cache-policy operand's nt bit
    return __builtin_bit_cast(uint32x4,
                              __builtin_amdgcn_raw_buffer_load_b128(buffer, offset, 0, NT));
}

// Packets between GPUs, on uncached memory: system scope (sc0 sc1) and nt keep them out of every
// cache even where a mapping is cached. asm, so a polling loop really reloads.
__device__ inline void store_nt(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc0 sc1 nt\n\ts_nop 1" ::"v"(ptr), "v"(val)
                 : "memory");
}

__device__ inline uint32x4 load_nt(const uint32x4 *ptr) {
    uint32x4 val;
    asm volatile("global_load_dwordx4 %0, %1, off sc0 sc1 nt\n\ts_waitcnt vmcnt(0)"
                 : "=v"(val)
                 : "v"(ptr)
                 : "memory");
    return val;
}

// Code that uses val stays after this point and memory accesses stay on their side of it: placed
// after later loads, it keeps the wait for val's load from holding them back.
template <typename T> __device__ inline void pin(T &val) {
    asm volatile("" : "+v"(val)::"memory");
}

// val as a value the compiler cannot see through, in a scalar register: loads whose address uses it
// go out from here, not hoisted with the loads before
__device__ inline int opaque(int val) {
    asm volatile("" : "+s"(val)::"memory");
    return val;
}

// __syncthreads also waits for every global load in flight; this waits for LDS accesses only.
__device__ inline void block_sync_lds() {
    asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
    __builtin_amdgcn_s_barrier();
}

// A raw buffer resource over bytes [base, base + size), for loads with cache-policy bits.
__device__ inline __amdgpu_buffer_rsrc_t raw_buffer(const void *base, int size) {
    return __builtin_amdgcn_make_buffer_rsrc(const_cast<void *>(base), 0, size, 0x00020000);
}

// An sc1 load of a T (4, 8 or 16 B) at a byte offset, counted by the compiler like any load (an asm
// load is not: the compiler may move its register before the data lands).
template <typename T = uint32x4>
__device__ inline T buffer_load_sc1(__amdgpu_buffer_rsrc_t buffer, int offset) {
    constexpr int SC1 = 16; // the cache-policy operand's sc1 bit
    if constexpr (sizeof(T) == 4) {
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b32(buffer, offset, 0, SC1));
    } else if constexpr (sizeof(T) == 8) {
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b64(buffer, offset, 0, SC1));
    } else {
        static_assert(sizeof(T) == 16);
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b128(buffer, offset, 0, SC1));
    }
}

// Loads N consecutive 16-byte packets with sc1, waiting once for all of them.
template <int N> __device__ inline void load_sc1(const uint32x4 *ptr, uint32x4 (&vals)[N]) {
    static_assert(N == 1 || N == 2);
    if constexpr (N == 1) {
        asm volatile("global_load_dwordx4 %0, %1, off sc1\n\ts_waitcnt vmcnt(0)"
                     : "=v"(vals[0])
                     : "v"(ptr)
                     : "memory");
    } else {
        asm volatile("global_load_dwordx4 %0, %2, off sc1\n\t"
                     "global_load_dwordx4 %1, %2, off offset:16 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(vals[0]), "=&v"(vals[1])
                     : "v"(ptr)
                     : "memory");
    }
}

// One lane's 32 B of an fp8 MFMA 16x16x128 operand: K bytes 16g..16g+15 and 64+16g..64+16g+15 of
// row (A) or column (B) l % 16, for g = l / 16 (ISA layout).
__device__ inline int32x8 load_fragment(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = *reinterpret_cast<const int32x4 *>(first);
    const int32x4 hi = *reinterpret_cast<const int32x4 *>(second);
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// load_fragment with nt, for weights read once a layer: they stream through L2 and the MALL instead
// of pushing out what is read again (data read ahead for the next kernel, the lm_head between steps)
__device__ inline int32x8 load_fragment_nt(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(first));
    const int32x4 hi = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(second));
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// D = A B for 16x16 fp8 e4m3 tiles over K = 128; lane l gets D[4 (l / 16) + i][l % 16] in element
// i. Zero scales make the compiler emit the instruction without block scaling.
__device__ inline floatx4 mfma_16x16x128_fp8(int32x8 a, int32x8 b) {
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a, b, floatx4{}, 0, 0, 0, 0, 0, 0);
}

// C + A B for 16x16 MXFP4 (e2m1) tiles over K = 128, D laid out as fp8's. Lane l holds K
// 32 g..32 g + 31 (g = l / 16) of row (A) or column (B) l % 16, two per byte with the lower K in
// the low nibble, and that block's e8m0 scale in byte SEL of scale_a / scale_b (127 = 1.0). Half
// the cycles of fp8.
template <int SEL_A = 0, int SEL_B = 0>
__device__ inline floatx4 mfma_16x16x128_fp4(int32x4 a, int32x4 b, int scale_a, int scale_b,
                                             floatx4 c = {}) {
    constexpr int E2M1 = 4; // cbsz / blgp: the operand format
    // the builtin takes fp8's 8 VGPRs, fp4 reads the first 4: zero padding, as CK, which the
    // compiler drops
    const int32x8 a8 = {a[0], a[1], a[2], a[3], 0, 0, 0, 0};
    const int32x8 b8 = {b[0], b[1], b[2], b[3], 0, 0, 0, 0};
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a8, b8, c, E2M1, E2M1, SEL_A, scale_a,
                                                            SEL_B, scale_b);
}

template <typename T> struct SumOp {
    __device__ static T op(const T &x, const T &y) { return x + y; }
};

template <typename T> struct MaxOp {
    __device__ static T op(const T &x, const T &y) { return x > y ? x : y; }
};

// Orders like the float, as an unsigned integer.
__device__ __forceinline__ uint32_t ordered_bits(float x) {
    const uint32_t bits = __float_as_uint(x);
    return (bits & 0x80000000u) ? ~bits : bits | 0x80000000u;
}

// Each lane gets the value of the lane that DPP_CTRL picks within its 16-lane row. bound_ctrl lets
// the compiler fold the move into the instruction that uses it.
template <int DPP_CTRL, typename T> __device__ inline T dpp_mov(T val) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(
        T, __builtin_amdgcn_mov_dpp(__builtin_bit_cast(int, val), DPP_CTRL, 0xF, 0xF, true));
}

template <typename T> __device__ inline T readlane(T val, int lane) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(T, __builtin_amdgcn_readlane(__builtin_bit_cast(int, val), lane));
}

// Reduces over each aligned group of WIDTH lanes; every lane gets its group's result. DPP within
// a 16-lane row; across rows, row 3 adds row 2 and then rows 0 + 1, and lane 63 is read out. No
// LDS round trip.
template <template <class> class Func, typename T, int WIDTH = THREADS_PER_WARP>
__device__ inline T WarpReduce(T val) {
    static_assert(WIDTH == 4 || WIDTH == 16 || WIDTH == THREADS_PER_WARP);
    val = Func<T>::op(dpp_mov<0xB1>(val), val); // quad_perm [1,0,3,2]
    val = Func<T>::op(dpp_mov<0x4E>(val), val); // quad_perm [2,3,0,1]
    if constexpr (WIDTH == 4) {
        return val;
    }
    val = Func<T>::op(dpp_mov<0x141>(val), val); // row_half_mirror
    val = Func<T>::op(dpp_mov<0x140>(val), val); // row_mirror
    if constexpr (WIDTH == THREADS_PER_WARP) {
        val = Func<T>::op(val, dpp_mov<0x142>(val)); // row_bcast:15, row r gets row r - 1
        val = Func<T>::op(val, dpp_mov<0x143>(val)); // row_bcast:31, rows 2, 3 get row 1
        val = readlane(val, 63);
    }
    return val;
}

// Every thread gets the result. Warps are combined in a fixed order so all blocks get the same
// bits. smem holds NUM_WARPS * N elements and can be reused as soon as this returns. LDS_ONLY
// syncs on LDS alone, leaving global loads in flight.
template <template <class> class Func, int BLOCK_SIZE, bool LDS_ONLY = false, typename T, int N>
__device__ inline void BlockReduce(T (&vals)[N], T *smem) {
    const auto sync = [] {
        if constexpr (LDS_ONLY) {
            block_sync_lds();
        } else {
            __syncthreads();
        }
    };
    constexpr int NUM_WARPS = BLOCK_SIZE / THREADS_PER_WARP;
    const int     warp_id   = threadIdx.x / THREADS_PER_WARP;
    const int     lane_id   = threadIdx.x % THREADS_PER_WARP;

#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = WarpReduce<Func>(vals[n]);
    }
    // not inside the loop above: a branch there would serialize the N independent reductions
    if (lane_id == 0) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            smem[warp_id * N + n] = vals[n];
        }
    }
    sync();
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = smem[n];
#pragma unroll
        for (int w = 1; w < NUM_WARPS; ++w) {
            vals[n] = Func<T>::op(vals[n], smem[w * N + n]);
        }
    }
    sync();
}

} // namespace infera_flash

// fp8 or MXFP4 GEMM of up to 4 rows of x by an aiter-preshuffled weight, a 16-row group of the
// weight at a time.
#pragma once

#include <type_traits>

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

// aiter-preshuffled weights come in groups of 16 rows; a group's 128-K block is a contiguous 2 KB
// (MXFP4: 1 KB, lane l of the fp4 MFMA reading its 16 B at 16 l)
constexpr int K_BLOCK_BYTES = 16 * 128;
// by format: that block's bytes, and a lane's share of it for the MFMA
template <bool MXFP4> constexpr int K_BLOCK_BYTES_OF = MXFP4 ? K_BLOCK_BYTES / 2 : K_BLOCK_BYTES;
template <bool MXFP4> using Fragment = std::conditional_t<MXFP4, int32x4, int32x8>;

// The dword of aiter's shuffle_scale layout holding the e8m0 of (row, group) of [rows, GROUPS]
// MXFP4 scales: it packs rows r, r + 16 of groups g, g + 4 (r % 32 < 16, g % 8 < 4), this one at
// byte group / 4 % 2 * 2 + row / 16 % 2. Returns its byte offset.
template <int GROUPS> __device__ inline int e8m0_dword(int row, int group) {
    return row / 32 * 32 * GROUPS + group / 8 * 256 + group % 4 * 64 + row % 16 * 4;
}

// What a wave of group_out needs of 16-row group `group` of a preshuffled [rows, K] fp8 weight: its
// quarter of the K blocks, and in lane j the scale of its K block j. The scales go out first.
template <int K>
__device__ __forceinline__ void load_group(const uint8_t *weight, const float *scale, int group,
                                           int32x8 (&w)[K / 128 / WAVES], float &w_scales) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    const int     kb0    = threadIdx.x / THREADS_PER_WARP * WAVE_K;
    w_scales             = scale[group / 8 * (K / 128) + kb0 + lane % WAVE_K];
    const uint8_t *src = weight + static_cast<size_t>(group) * 16 * K + kb0 * K_BLOCK_BYTES +
                         lane / 16 * 256 + lane % 16 * 16;
#pragma unroll
    for (int j = 0; j < WAVE_K; ++j) {
        w[j] = load_fragment(src + j * K_BLOCK_BYTES, src + j * K_BLOCK_BYTES + 1024);
    }
}

// load_group for an MXFP4 weight (e2m1 pairs) and its e8m0 in aiter shuffle_scale's layout: lane
// l's 16 B of each of its wave's K blocks, and a dword per two blocks holding their scales of its
// row l % 16 and K 32 (l / 16) on (e8m0_dword: bytes 0 and 2 once shifted right by group % 2 * 8).
template <int K>
__device__ __forceinline__ void load_group_mxfp4(const uint8_t *weight, const uint8_t *scale,
                                                 int group, int32x4 (&w)[K / 128 / WAVES],
                                                 int (&w_e8m0)[K / 128 / WAVES / 2]) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    const int     kb0    = threadIdx.x / THREADS_PER_WARP * WAVE_K;
    static_assert(WAVE_K % 2 == 0);
#pragma unroll
    for (int p = 0; p < WAVE_K / 2; ++p) {
        w_e8m0[p] = *reinterpret_cast<const int *>(
            scale + e8m0_dword<K / 32>(group * 16 + lane % 16, 4 * (kb0 + 2 * p) + lane / 16));
    }
    const uint8_t *src = weight + static_cast<size_t>(group) * 8 * K +
                         kb0 * K_BLOCK_BYTES_OF<true> + lane * 16;
#pragma unroll
    for (int j = 0; j < WAVE_K; ++j) {
        w[j] = *reinterpret_cast<const int32x4 *>(src + j * K_BLOCK_BYTES_OF<true>);
    }
}

// LDS of group_store, for up to MAX_TOKENS rows of x
template <int MAX_TOKENS>
struct GroupSmem {
    floatx4  tiles[Hw::BLOCK_SIZE];   // each wave's 16x16 partial sum
    bfloat16 out[MAX_TOKENS * 16]; // the group's outputs, [M][16]
};

// The group's [M][16] outputs from each wave's 16x16 partial sum acc: the 4 added in wave order,
// rounded to bf16 and stored 16 B per half row at out (row stride `stride`), with sc1 when other
// XCDs read them back.
template <int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_store(floatx4 acc, GroupSmem<MAX_TOKENS> &s, bfloat16 *out,
                                            int stride) {
    static_assert(NUM_TOKENS <= MAX_TOKENS);
    const int tid = threadIdx.x;
    s.tiles[tid]  = acc;
    block_sync_lds();
    // thread (m, r): row r of token m, at lane 16 (r / 4) + m of each wave's tile, element r % 4
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        s.out[tid] = static_cast<bfloat16>(sum);
    }
    block_sync_lds();
    if (tid < 2 * NUM_TOKENS) {
        const uint32x4 val = reinterpret_cast<const uint32x4 *>(s.out)[tid];
        auto          *dst = reinterpret_cast<uint32x4 *>(out + tid / 2 * stride + tid % 2 * 8);
        if constexpr (SC1) {
            store_sc1(dst, val);
        } else {
            *dst = val;
        }
    }
}

// A wave's sum over N fp8 K blocks from kb0: w and, in lane j, the scale of block kb0 + j as
// load_group loads them; x [M][K] in LDS with its scales [M][K / 128], this lane's column token.
template <int K, int N>
__device__ __forceinline__ floatx4 fp8_blocks(const int32x8 (&w)[N], float w_scales,
                                              const uint8_t *x, const float *x_scale, int token,
                                              int kb0) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    floatx4   acc  = {};
#pragma unroll
    for (int j = 0; j < N; ++j) {
        const uint8_t *xq = x + token * K + (kb0 + j) * 128 + lane / 16 * 16;
        acc += mfma_16x16x128_fp8(w[j], load_fragment(xq, xq + 64)) *
               (readlane(w_scales, j) * x_scale[token * (K / 128) + kb0 + j]);
    }
    return acc;
}

// The group's [M][16] outputs (group_store) from the fp8 x [M][K] in LDS (scales [M][K / 128]):
// each wave's partial sum over its K blocks.
template <int K, int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_out(const int32x8 (&w)[K / 128 / WAVES], float w_scales,
                                          const uint8_t *x, const float *x_scale,
                                          GroupSmem<MAX_TOKENS> &s, bfloat16 *out, int stride) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    // columns past M repeat token M - 1 and are dropped
    const floatx4 acc = fp8_blocks<K, WAVE_K>(w, w_scales, x, x_scale,
                                              min(lane % 16, NUM_TOKENS - 1),
                                              threadIdx.x / THREADS_PER_WARP * WAVE_K);
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

// A wave's sum over N MXFP4 K blocks from kb0 (even: block pairs share a dword): w and w_e8m0 as
// load_group_mxfp4 loads them (the e8m0 at bytes 0 and 2 once shifted right by `shift`), x
// [M][K / 2] in LDS with its e8m0 [M][K / 32], this lane's column token. The scales go into the
// instruction, which accumulates.
template <int K, int N>
__device__ __forceinline__ floatx4 mxfp4_blocks(const int32x4 (&w)[N], const int (&w_e8m0)[N / 2],
                                                int shift, const uint8_t *x, const uint8_t *x_e8m0,
                                                int token, int kb0) {
    static_assert(N % 2 == 0);
    const int  lane = threadIdx.x % THREADS_PER_WARP;
    const auto x_of = [&](int b) {
        return *reinterpret_cast<const int32x4 *>(x + token * K / 2 + b * 64 + lane / 16 * 16);
    };
    const auto e_of = [&](int b) { return x_e8m0[token * K / 32 + 4 * b + lane / 16]; };
    floatx4    acc  = {};
#pragma unroll
    for (int i = 0; i < N / 2; ++i) {
        const int b       = kb0 + 2 * i;
        const int w_scale = w_e8m0[i] >> shift;
        acc = mfma_16x16x128_fp4<0, 0>(w[2 * i], x_of(b), w_scale, e_of(b), acc);
        acc = mfma_16x16x128_fp4<2, 0>(w[2 * i + 1], x_of(b + 1), w_scale, e_of(b + 1), acc);
    }
    return acc;
}

// group_out for group `group` of an MXFP4 weight (load_group_mxfp4) and x [M][K / 2] in LDS with
// its e8m0 [M][K / 32].
template <int K, int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_out_mxfp4(const int32x4 (&w)[K / 128 / WAVES],
                                                const int (&w_e8m0)[K / 128 / WAVES / 2], int group,
                                                const uint8_t *x, const uint8_t *x_e8m0,
                                                GroupSmem<MAX_TOKENS> &s, bfloat16 *out,
                                                int stride) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    // columns past M repeat token M - 1 and are dropped
    const floatx4 acc = mxfp4_blocks<K, WAVE_K>(w, w_e8m0, group % 2 * 8, x, x_e8m0,
                                                min(lane % 16, NUM_TOKENS - 1),
                                                threadIdx.x / THREADS_PER_WARP * WAVE_K);
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

} // namespace infera_flash

// MI355X as our kernels use it: block b runs on XCD b % NUM_XCDS, and a kernel whose blocks wait on
// each other runs NUM_BLOCKS of them, all resident.
#pragma once

namespace infera_flash {

constexpr int THREADS_PER_WARP = 64;

struct Hw {
    static constexpr int NUM_BLOCKS = 256; // one per CU
    static constexpr int NUM_XCDS   = 8;
    static constexpr int BLOCK_SIZE = 256;
    // all of a CU's LDS, so each CU runs exactly one block
    static constexpr int SMEM_SIZE = 160 * 1024;
};

constexpr int WAVES = Hw::BLOCK_SIZE / THREADS_PER_WARP; // a block's

} // namespace infera_flash

// Math the kernels share, rounded as HF rounds: bf16 pairs, fp8 conversion and quant, MXFP4 quant
// (as Quark), RoPE, the residual add and RMSNorm.
#pragma once

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

using bfloat16x2 = bfloat16 __attribute__((ext_vector_type(2)));

// bf16 pairs to floats (exact) and back (round to nearest even), for packed floatx2 math
__device__ inline floatx2 to_float2(bfloat16x2 v) { return __builtin_convertvector(v, floatx2); }
__device__ inline bfloat16x2 to_bf16x2(floatx2 v) { return __builtin_convertvector(v, bfloat16x2); }

constexpr float FP8_MAX = 448.0f; // largest finite e4m3fn

using bfloat16x8 = bfloat16 __attribute__((ext_vector_type(8)));

// 8 fp8 values as bf16, exactly, 2 per instruction
__device__ inline bfloat16x8 fp8x8_to_bf16(uint32_t lo, uint32_t hi) {
    const bfloat16x2 v0 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(lo, 1.0f, false);
    const bfloat16x2 v1 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(lo, 1.0f, true);
    const bfloat16x2 v2 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(hi, 1.0f, false);
    const bfloat16x2 v3 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(hi, 1.0f, true);
    return __builtin_shufflevector(__builtin_shufflevector(v0, v1, 0, 1, 2, 3),
                                   __builtin_shufflevector(v2, v3, 0, 1, 2, 3), 0, 1, 2, 3, 4, 5, 6,
                                   7);
}

// aiter's MXFP4 quant (MxScaleRoundMode RoundUp, its default) of a 32-value group held by 4
// consecutive lanes, 8 values each: stores this lane's 8 e2m1 codes (4 B, the lower K in the low
// nibble) to q and returns the group's e8m0 scale, 2^(e8m0 - 127), amax / 6 rounded up to a power
// of two; values round to nearest even.
__device__ inline int quant_mxfp4(const bfloat16 (&x)[8], uint8_t *q) {
    float amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 8; ++j) {
        amax = fmaxf(amax, fabsf(static_cast<float>(x[j])));
    }
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 4>(__float_as_uint(amax)));
    const uint32_t ratio = __float_as_uint(amax / 6.0f);
    const int      e8m0  = min(static_cast<int>((ratio >> 23) + ((ratio & 0x7fffffu) != 0u)), 254);
    // the convert divides by scale; its byte index must be a constant, so one call per byte
    const float scale = __uint_as_float(static_cast<uint32_t>(e8m0) << 23);
    const auto  f     = [&](int j) { return static_cast<float>(x[j]); };
    uint32_t    codes = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(0, f(0), f(1), scale, 0);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(2), f(3), scale, 1);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(4), f(5), scale, 2);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(6), f(7), scale, 3);
    *reinterpret_cast<uint32_t *>(q) = codes;
    return e8m0;
}

// HF's interleaved RoPE of the pair (x0, x1) by the position's (c, s), each bf16 op rounded: an
// FMA would skip the products' rounding
__device__ inline void rope_pair(float &x0, float &x1, float c, float s) {
#pragma clang fp contract(off)
    const auto  bf16 = [](float v) { return static_cast<float>(static_cast<bfloat16>(v)); };
    const float y0   = bf16(bf16(x0 * c) - bf16(x1 * s));
    x1               = bf16(bf16(x1 * c) + bf16(x0 * s));
    x0               = y0;
}

// HF finegrained-fp8 quant of a 1x128 group held by 16 consecutive lanes, 8 values each: stores
// this lane's 8 fp8 values to q and returns the group's scale. A multiply and v_rcp where HF
// divides move a few values by one fp8 step.
__device__ inline float quant_fp8(const bfloat16 (&x)[8], uint8_t *q) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
    floatx2     v[4];
    float       amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        v[j] = to_float2(x2[j]); // pairs, so a scale_row before stays packed
        amax = fmaxf(amax, fmaxf(fabsf(v[j].x), fabsf(v[j].y)));
    }
    // amax >= 0 orders like its bits: an integer max, whose DPP moves fold into it
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 16>(__float_as_uint(amax)));
    const float scale     = amax * (1.0f / FP8_MAX);
    const float inv_scale = __builtin_amdgcn_rcpf(fmaxf(scale, 1e-12f));
    uint32_t    fp8[2];
#pragma unroll
    for (int j = 0; j < 2; ++j) {
        const floatx2 lo = v[2 * j] * inv_scale; // packed: two values per instruction
        const floatx2 hi = v[2 * j + 1] * inv_scale;
        // the second convert overwrites the half the first keeps: no need to zero it
        const int any    = __builtin_bit_cast(int, lo.x);
        fp8[j]           = __builtin_amdgcn_cvt_pk_fp8_f32(
            hi.x, hi.y, __builtin_amdgcn_cvt_pk_fp8_f32(lo.x, lo.y, any, false), true);
    }
    *reinterpret_cast<uint2 *>(q) = *reinterpret_cast<const uint2 *>(fp8);
    return scale;
}

// x's rows quantized into LDS, each thread holding LOADS x 8 values of every row (as rms_norm's
// x): fp8 as HF, scales [M][COLS / 128], or MXFP4 as aiter, e8m0 [M][COLS / 32]
template <int NUM_TOKENS, int LOADS, bool MXFP4>
__device__ __forceinline__ void quant_rows(const bfloat16 (&x)[NUM_TOKENS][LOADS][8], uint8_t *q,
                                           void *scales) {
    constexpr int COLS   = LOADS * 8 * Hw::BLOCK_SIZE;
    const int     tid    = threadIdx.x;
    const auto    offset = [&](int m, int i) { return m * COLS + (i * Hw::BLOCK_SIZE + tid) * 8; };
    if constexpr (MXFP4) {
        int e8m0[NUM_TOKENS][LOADS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < LOADS; ++i) {
                e8m0[m][i] = quant_mxfp4(x[m][i], q + offset(m, i) / 2);
            }
        }
        // not inside the loop above: a branch there would serialize the groups
        if (tid % 4 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < LOADS; ++i) {
                    static_cast<uint8_t *>(scales)[offset(m, i) / 32] = e8m0[m][i];
                }
            }
        }
    } else {
        float s[NUM_TOKENS][LOADS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < LOADS; ++i) {
                s[m][i] = quant_fp8(x[m][i], q + offset(m, i));
            }
        }
        if (tid % 16 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < LOADS; ++i) {
                    static_cast<float *>(scales)[offset(m, i) / 128] = s[m][i];
                }
            }
        }
    }
}

// HF's act_fn(gate) * up of the linears' bf16 outputs: silu and the product each round to bf16
__device__ __forceinline__ bfloat16 silu_mul(bfloat16 gate, bfloat16 up) {
    const float g    = gate;
    const float silu = static_cast<bfloat16>(g / (1.0f + expf(-g)));
    return static_cast<bfloat16>(silu * static_cast<float>(up));
}

// x += residual as HF adds them, in bf16; each thread holds LOADS x 8 values of every row.
template <int NUM_TOKENS, int LOADS>
__device__ __forceinline__ void add_rows(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                         const bfloat16 (&residual)[NUM_TOKENS][LOADS][8]) {
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            auto       *x2 = reinterpret_cast<bfloat16x2 *>(x[m][i]);
            const auto *r2 = reinterpret_cast<const bfloat16x2 *>(residual[m][i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                x2[j] = to_bf16x2(to_float2(x2[j]) + to_float2(r2[j]));
            }
        }
    }
}

// sum2 += x^2 over 8 values, two at a time
__device__ __forceinline__ void add_squares(floatx2 &sum2, const bfloat16 (&x)[8]) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const floatx2 v = to_float2(x2[j]);
        sum2 += v * v;
    }
}

// v as computed, in VGPRs: the compiler would split a pair whose halves are used apart into one
// convert and one multiply per value
template <typename T> __device__ __forceinline__ void keep_pair(T &v) {
    asm volatile("" : "+v"(v));
}

// 8 values of a row as HF's RMSNorm leaves them: x = bf16(gamma * bf16(x * factor)), gamma in
// float pairs
__device__ __forceinline__ void scale_row(bfloat16 (&x)[8], const floatx2 (&gamma)[4],
                                          float factor) {
    auto *x2 = reinterpret_cast<bfloat16x2 *>(x);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const floatx2 normed = to_float2(to_bf16x2(to_float2(x2[j]) * factor));
        x2[j]                = to_bf16x2(gamma[j] * normed);
        keep_pair(x2[j]);
    }
}

__device__ __forceinline__ void scale_row(bfloat16 (&x)[8], const bfloat16 (&gamma)[8],
                                          float factor) {
    const auto *g2 = reinterpret_cast<const bfloat16x2 *>(gamma);
    floatx2     g[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        g[j] = to_float2(g2[j]);
    }
    scale_row(x, g, factor);
}

// HF's RMSNorm of M rows, each thread holding LOADS x 8 values of every row (so rows of LOADS x 8 x
// BLOCK_SIZE). LDS_ONLY as BlockReduce's.
template <int NUM_TOKENS, int LOADS, bool LDS_ONLY>
__device__ __forceinline__ void rms_norm(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                         const bfloat16 (&gamma)[LOADS][8], float eps,
                                         float *reduce) {
    constexpr int COLS = LOADS * 8 * Hw::BLOCK_SIZE;
    float sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        sums[m] = sum2.x + sum2.y;
    }
    BlockReduce<SumOp, Hw::BLOCK_SIZE, LDS_ONLY>(sums, reduce);
    floatx2 g[LOADS][4]; // once for all rows
#pragma unroll
    for (int i = 0; i < LOADS; ++i) {
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            g[i][j] = to_float2(reinterpret_cast<const bfloat16x2 *>(gamma[i])[j]);
            keep_pair(g[i][j]);
        }
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        // torch's mean multiplies by 1/N rather than dividing
        const float factor = rsqrtf(sums[m] * (1.0f / COLS) + eps);
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            scale_row(x[m][i], g[i], factor);
        }
    }
}

} // namespace infera_flash

// The blocks of one kernel waiting on each other: each block publishes 16 B packets in its slot of
// a sync workspace, tagged with the call's epoch.
#pragma once

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

// bytes: a 64 B slot per block, 4 packets of 16 B that each kernel numbers for itself; zero it once
// at allocation, never between calls
constexpr int WORKSPACE_SIZE = Hw::NUM_BLOCKS * 64;
// a block's slot in a sync workspace, in 16 B packets
constexpr int PACKETS_PER_SLOT = WORKSPACE_SIZE / Hw::NUM_BLOCKS / sizeof(uint32x4);

// One more than the epoch this block published in its slot last call, past 0 when it wraps (slots
// and tagged buffers start zeroed): stream order makes that store visible to this plain load. A
// vector load: a scalar one holds back the scalar loads after it, those of x's address among them.
__device__ __forceinline__ uint32_t next_epoch(const uint32x4 *slot) {
    const uint32_t epoch =
        __builtin_amdgcn_raw_buffer_load_b32(raw_buffer(slot, sizeof(uint32x4)), 12, 0, 0) + 1;
    return epoch ? epoch : 1;
}

// The packet at src once it shows this call's epoch (sc1 loads: other XCDs write it).
__device__ __forceinline__ uint32x4 wait_packet(const uint32x4 *src, uint32_t epoch) {
    uint32x4 vals[1];
    do {
        load_sc1(src, vals);
    } while (vals[0][3] != epoch);
    return vals[0];
}

// Thread t < count waits until packet `packet` of block first + t's slot shows this call's epoch,
// then the block syncs.
__device__ __forceinline__ void wait_for(const uint32x4 *slots, int packet, int first, int count,
                                         uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < count) {
        wait_packet(slots + (first + threadIdx.x) * PACKETS_PER_SLOT + packet, epoch);
    }
    __syncthreads();
}

// The same over blocks block_of(t), t < count.
template <typename BlockOf>
__device__ __forceinline__ void wait_for(const uint32x4 *slots, int packet, int count,
                                         BlockOf block_of, uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < count) {
        wait_packet(slots + block_of(static_cast<int>(threadIdx.x)) * PACKETS_PER_SLOT + packet,
                    epoch);
    }
    __syncthreads();
}

// the stores before are asm, which the compiler does not count: wait for them, then the packet
// (LOCAL: for this XCD's blocks, through its L2), carrying a and b
template <bool LOCAL = false>
__device__ __forceinline__ void publish(uint32x4 *packet, uint32_t epoch, uint32_t a = 0u,
                                        uint32_t b = 0u) {
    asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    __syncthreads();
    if (threadIdx.x == 0) {
        if constexpr (LOCAL) {
            store_l2(packet, uint32x4{a, b, 0u, epoch});
        } else {
            store_sc1(packet, uint32x4{a, b, 0u, epoch});
        }
    }
}

// thread t < count waits until packet `packet` of block block_of(t), on this XCD, shows this
// call's epoch (nt loads, from the L2), then the block syncs
template <typename BlockOf>
__device__ __forceinline__ void wait_local(const uint32x4 *slots, int packet, int count,
                                           BlockOf block_of, uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < count) {
        uint32x4 v;
        do {
            asm volatile("global_load_dwordx4 %0, %1, off nt\n\ts_waitcnt vmcnt(0)"
                         : "=v"(v)
                         : "v"(slots + block_of(threadIdx.x) * PACKETS_PER_SLOT + packet)
                         : "memory");
        } while (v[3] != epoch);
    }
    __syncthreads();
}

} // namespace infera_flash

// The all-reduce over the TP ranks that ends moe's down and row_linear_ar, written for GLM-5's 6144
// rows = 256 blocks x 24.
#pragma once

#include "common/device.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// Block k of every rank swaps its share of the [M, HIDDEN_SIZE] output with block k of the others.
struct AllReduceParams {
    bfloat16 *out;        // [M, HIDDEN_SIZE]
    bool      accumulate; // out = bf16(bf16(sum) + prior), HF's residual add
    const bfloat16 *prior; // [M, HIDDEN_SIZE] the residual
    // every rank's AR_BUFFER_SIZE receive buffer, IPC-mapped; per-block call counters; one of each
    // per process, shared by every kernel that exchanges across the ranks (lm_head_argmax too).
    // World 1 means no all-reduce.
    void *recv[Config::MAX_RANKS];
    int  *calls;
    int   rank;
    int   world;
};

// This block's last call number, as a vector load (a scalar one holds back the loads after it) that
// reads 0 past the end (world 1).
__device__ inline uint32_t last_call(const AllReduceParams &p) {
    return __builtin_amdgcn_raw_buffer_load_b32(
        raw_buffer(p.calls, p.world > 1 ? Config::NUM_BLOCKS * sizeof(int) : 0),
        blockIdx.x * sizeof(int), 0, 0);
}

// The row split of moe's down and row_linear_ar: block k owns output rows 24k .. 24k + 23. Blocks
// 2j and 2j + 1 share 16-row groups 3j .. 3j + 2, the even one taking group 3j and rows 0-7 of
// 3j + 1, the odd one rows 8-15 of 3j + 1 and group 3j + 2. Waves 0 and 1 take the full group,
// waves 2 and 3 the half group, each pair splitting K; in the half group lanes 8-15 repeat the rows
// of lanes 0-7 and their C rows are dropped.
static_assert(Config::AR_ROWS == 24); // the split: one 16-row group and half of another
__device__ inline int split_group(int block, int wave) {
    return block / 2 * 3 + (wave < 2 ? 2 * (block & 1) : 1);
}
__device__ inline int split_group(int wave) { return split_group(blockIdx.x, wave); }
// the row of its 16-row group this lane loads
__device__ inline int split_row(int wave, int lane) {
    return wave < 2 ? lane % 16 : lane % 8 + 8 * (blockIdx.x & 1);
}

// The residual this thread adds in all_reduce_rows (0 without accumulate). Load it well before the
// exchange: the exchange's poll waits for every load issued before it.
template <int NUM_TOKENS>
__device__ inline float all_reduce_residual(const AllReduceParams &p) {
    const int tid = threadIdx.x;
    if (p.accumulate && tid < Config::AR_ROWS * NUM_TOKENS) {
        return static_cast<float>(p.prior[tid / Config::AR_ROWS * Config::HIDDEN_SIZE +
                                          Config::AR_ROWS * blockIdx.x + tid % Config::AR_ROWS]);
    }
    return 0.0f;
}

// packet i of block `block`'s share from rank src in the receive buffer, for call's parity
__device__ __forceinline__ uint32_t ar_slot(uint32_t call, int src, int block, int i) {
    return ((call % 2 * Config::MAX_RANKS + src) * Config::NUM_BLOCKS + block) *
               Config::AR_PACKETS +
           i;
}

// all_reduce_rows' LDS
struct RowsSmem {
    floatx4  tiles[Config::BLOCK_SIZE]; // each wave's 16x16 result
    // every rank's [M][AR_ROWS] share
    bfloat16 rows[Config::MAX_RANKS][Config::AR_ROWS * Config::MAX_NUM_TOKENS];
};

// The end of down and row_linear_ar: block k's output rows from its 4 waves' 16x16 tiles, split as
// above, summed over the TP ranks, plus prior (all_reduce_residual) when accumulating. SC1: the rows
// go out in sc1 stores, for other XCDs in the same kernel.
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void all_reduce_rows(const AllReduceParams &p, RowsSmem &s, floatx4 acc,
                                                uint32_t call, float prior) {
    constexpr int ROWS  = Config::AR_ROWS;
    const int     tid   = threadIdx.x;
    const int     block = blockIdx.x;
    const int     odd   = block & 1;
    bfloat16     *at    = p.out + tid / ROWS * Config::HIDDEN_SIZE + ROWS * block + tid % ROWS;
    s.tiles[tid]        = acc;
    block_sync_lds(); // loads the block no longer needs may still be in flight
    if (tid < ROWS * NUM_TOKENS) {
        const int m = tid / ROWS;
        const int q = tid % ROWS; // our output row 24k + q
        // even CUs: the full group's 16 rows, then the half group's 8; odd CUs the other way round
        const bool     full = odd ? q >= 8 : q < 16;
        const int      c    = full ? q - 8 * odd : q - 16 + 16 * odd;
        const floatx4 *tile = s.tiles + (full ? 0 : 2) * THREADS_PER_WARP + 16 * (c / 4) + m;
        s.rows[p.rank][tid] =
            static_cast<bfloat16>(tile[0][c % 4] + tile[THREADS_PER_WARP][c % 4]);
    }
    block_sync_lds();

    // all-reduce: block k swaps its rows with block k of every other rank. A packet is 6 outputs and
    // the call number in one 16 B store, which lands whole (none torn in 5.5M across XGMI, measured;
    // 8 B halves each with the number cost a third more bytes, 1.1 us a layer at M = 4), so a packet
    // showing this call is complete. Two buffers by call parity: no rank gets two calls ahead
    if (p.world > 1) {
        constexpr int PACKETS = ROWS * NUM_TOKENS / 6;
        if (tid < (p.world - 1) * PACKETS) {
            const int       other = (p.rank + 1 + tid / PACKETS) % p.world;
            const int       i     = tid % PACKETS;
            const uint32_t *mine  = reinterpret_cast<const uint32_t *>(s.rows[p.rank]) + 3 * i;
            store_nt(static_cast<uint32x4 *>(p.recv[other]) + ar_slot(call, p.rank, block, i),
                     uint32x4{mine[0], mine[1], mine[2], call});
            const uint32x4 *src =
                static_cast<const uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, i);
            uint32x4 packet;
            do {
                packet = load_nt(src);
            } while (packet.w != call);
            uint32_t *rows = reinterpret_cast<uint32_t *>(s.rows[other]) + 3 * i;
            rows[0]        = packet.x;
            rows[1]        = packet.y;
            rows[2]        = packet.z;
        }
        block_sync_lds();
        if (tid == 0) {
            p.calls[block] = call;
        }
    }
    // in rank order, so every rank gets the same bits
    if (tid < ROWS * NUM_TOKENS) {
        float sum = 0.0f;
        for (int r = 0; r < p.world; ++r) {
            sum += static_cast<float>(s.rows[r][tid]);
        }
        const bfloat16 val =
            p.accumulate ? static_cast<bfloat16>(static_cast<float>(static_cast<bfloat16>(sum)) + prior)
                         : static_cast<bfloat16>(sum);
        if constexpr (SC1) {
            store_sc1(at, val);
        } else {
            *at = val;
        }
    }
}

} // namespace infera_flash::glm5

// GLM-5.3 on 8 GPUs (TP8): the sizes every GLM-5 kernel is written for, per card where noted.
#pragma once

#include "common/hw.h"

namespace infera_flash::glm5 {

struct Config : Hw {
    static constexpr int   HIDDEN_SIZE           = 6144;
    static constexpr int   QUANT_GROUP_SIZE      = 128; // one fp8 scale per 1x128 of activations
    static constexpr int   NUM_GROUPS            = HIDDEN_SIZE / QUANT_GROUP_SIZE;
    static constexpr int   NUM_EXPERTS           = 256;
    static constexpr int   INTERMEDIATE_SIZE     = 256; // per card: 2048 / TP8
    static constexpr int   TOP_K                 = 8;
    static constexpr float ROUTED_SCALING_FACTOR = 2.5f;
    static constexpr int   MAX_NUM_TOKENS        = 4; // rows a decode call takes: MTP k=3 verifies 4
    // attention per card: q_a_proj's rows, kv_a_proj_with_mqa's (the kv latent, then the rope
    // part of k), qkv_a's (both), q_b_proj's; o_proj's K
    static constexpr int   Q_LORA_RANK           = 2048;
    static constexpr int   KV_LORA_RANK          = 512;
    static constexpr int   QK_ROPE_DIM           = 64;
    static constexpr int   QK_NOPE_DIM           = 192;
    static constexpr int   MLA_HEADS             = 8; // per card
    static constexpr int   V_HEAD_DIM            = 256;
    static constexpr int   QKV_A_ROWS            = Q_LORA_RANK + KV_LORA_RANK + QK_ROPE_DIM;
    static constexpr int   Q_B_ROWS              = MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM);
    static constexpr int   O_PROJ_K              = MLA_HEADS * V_HEAD_DIM;
    // the dense layers' MLP per card: gate_proj's rows, up_proj's (12288 / TP8)
    static constexpr int   DENSE_ROWS            = 1536;
    // the MTP layer's eh_proj rows per card (6144 / TP8)
    static constexpr int   MTP_ROWS              = HIDDEN_SIZE / 8;
    // the DSA indexer (replicated): heads, head dim, tokens per ki page
    static constexpr int   INDEX_HEADS           = 32;
    static constexpr int   INDEX_DIM             = 128;
    static constexpr int   INDEX_PAGE            = 64;
    static constexpr int   INDEX_TOPK            = 2048;
    // ExpertTable slots: the shared expert, then the most distinct experts M tokens can pick
    static constexpr int   MAX_SLOTS             = MAX_NUM_TOKENS * TOP_K + 1;
    // the shared expert's id: its weights come after the routed ones
    static constexpr int   SHARED_EXPERT         = NUM_EXPERTS;
    // the all-reduce (AllReduceParams): block k sums output rows AR_ROWS k .., a 16 B packet
    // carrying 6 of its AR_ROWS x M; receive buffer [call parity][source rank][block][packet]
    static constexpr int MAX_RANKS      = 8;
    static constexpr int AR_ROWS        = HIDDEN_SIZE / NUM_BLOCKS;
    static constexpr int AR_PACKETS     = AR_ROWS * MAX_NUM_TOKENS / 6;
    static constexpr int AR_BUFFER_SIZE = 2 * MAX_RANKS * NUM_BLOCKS * AR_PACKETS * 16;
};

// each thread's 16 B chunks of a HIDDEN_SIZE row, a block's threads covering it
constexpr int ROW_LOADS = Config::HIDDEN_SIZE / (Config::BLOCK_SIZE * 8);
static_assert(ROW_LOADS * Config::BLOCK_SIZE * 8 == Config::HIDDEN_SIZE);

} // namespace infera_flash::glm5

// The MoE layer in one kernel (moe.hip), one block per CU, and its device code, for that kernel and
// the layer kernel.
#pragma once

#include <type_traits>

#include "common/gemm.h"
#include "common/math.h"
#include "common/sync.h"
#include "glm5/all_reduce.h"
#include "glm5/config.h"
#include "aklr/norm.h"

namespace infera_flash::glm5 {

// The experts to run: the shared one first, then the picked routed ones in id order, with each
// token's weight (1 for the shared expert, 0 where a token didn't pick a routed one). Weights come
// first so each row is 16 B aligned.
struct ExpertTable {
    float w[Config::MAX_SLOTS][Config::MAX_NUM_TOKENS];
    int   ids[Config::MAX_SLOTS]; // -1 past count in the copies written out
    int   count;
};

// down of every expert in the table times its routing weight, summed in table order, then over the
// TP ranks.
struct DownParams {
    const bfloat16 *h; // MoeParams::act
    // [NUM_EXPERTS + 1, HIDDEN_SIZE, INTERMEDIATE_SIZE] in gate_up's format, preshuffled like its
    // weights: fp8 with scales [NUM_EXPERTS + 1, NUM_GROUPS, 2], one per 128 x 128 block, or MXFP4
    // with scales [NUM_EXPERTS + 1, HIDDEN_SIZE, INTERMEDIATE_SIZE / 32] shuffled like its scales
    const uint8_t  *weight;
    const void     *weight_scale;
    AllReduceParams ar;
};

// Shapes use M = num_tokens. The whole MoE layer in one kernel: residual add, RMSNorm, router, x
// quant, sync (1), top-k, grouping, gate_up, sync (2) on its h, then down and the all-reduce.
struct MoeParams {
    const bfloat16 *h;             // [M, HIDDEN_SIZE] attention output, or the stream (no residual)
    const bfloat16 *residual;      // [M, HIDDEN_SIZE], or null: h already holds it
    const bfloat16 *gamma;         // [HIDDEN_SIZE] post-attention RMSNorm weight
    const bfloat16 *router_weight; // [NUM_EXPERTS, HIDDEN_SIZE]
    const float    *router_bias;   // [NUM_EXPERTS]
    void           *workspace;     // WORKSPACE_SIZE bytes
    bfloat16       *residual_out;  // [M, HIDDEN_SIZE] h + residual
    float           epsilon;
    float           routed_scaling_factor;
    ExpertTable    *table;          // the grouping, written by block 0 (the moe op only)
    // [NUM_EXPERTS + 1, 2 * INTERMEDIATE_SIZE, HIDDEN_SIZE], gate rows then up rows, preshuffled by
    // aiter shuffle_weight(w, (16, 16)): fp8 with fp32 scales [NUM_EXPERTS + 1, 4, NUM_GROUPS], one
    // per 128 x 128 block, or (mxfp4) e2m1 pairs, the lower K in the low nibble, with e8m0 scales
    // [NUM_EXPERTS + 1, 2 * INTERMEDIATE_SIZE, HIDDEN_SIZE / 32] in aiter shuffle_scale's layout
    // (e8m0_dword); x and h are then quantized as aiter does (quant_mxfp4)
    bool           mxfp4;
    const uint8_t *gate_up_weight;
    const void    *gate_up_scale;
    // gate_up's h = silu(x gate^T) * (x up^T), rounded as HF does: [MAX_SLOTS, MAX_NUM_TOKENS,
    // INTERMEDIATE_SIZE], table slot order
    bfloat16 *act;
    // per-block debug outputs [NUM_BLOCKS, M, ...]: y, x quantized, its scales (the LDS bytes),
    // logits, top-k ids, weights; then each block's expert table [NUM_BLOCKS]
    bfloat16    *y_dbg;
    uint8_t     *q_dbg;
    uint8_t     *s_dbg;
    float       *logits_dbg;
    int         *ids_dbg;
    float       *w_dbg;
    ExpertTable *table_dbg;
    DownParams   down; // its h is act
};

void moe_launch(const MoeParams &params, int num_tokens, bool debug, hipStream_t stream);

// LDS layout, byte offsets into the dynamic smem
// x fp8 [MAX_NUM_TOKENS][HIDDEN_SIZE] or MXFP4 [MAX_NUM_TOKENS][HIDDEN_SIZE / 2], row-major
constexpr int SMEM_X_OFFSET = 0;
// x scales fp32 [MAX_NUM_TOKENS][NUM_GROUPS], or e8m0 [MAX_NUM_TOKENS][HIDDEN_SIZE / 32]: as many
// bytes
constexpr int SMEM_X_SCALE_OFFSET = SMEM_X_OFFSET + Config::MAX_NUM_TOKENS * Config::HIDDEN_SIZE;
static_assert(Config::NUM_GROUPS * sizeof(float) == Config::HIDDEN_SIZE / 32);
// router logits fp32 [MAX_NUM_TOKENS][NUM_EXPERTS], gathered from all blocks
constexpr int SMEM_LOGITS_OFFSET =
    SMEM_X_SCALE_OFFSET + Config::MAX_NUM_TOKENS * Config::NUM_GROUPS * sizeof(float);
// top-k expert ids int32 and weights fp32, each [MAX_NUM_TOKENS][TOP_K]
constexpr int SMEM_TOPK_IDS_OFFSET =
    SMEM_LOGITS_OFFSET + Config::MAX_NUM_TOKENS * Config::NUM_EXPERTS * sizeof(float);
constexpr int SMEM_TOPK_W_OFFSET =
    SMEM_TOPK_IDS_OFFSET + Config::MAX_NUM_TOKENS * Config::TOP_K * sizeof(int);
// grouping: a bit per expert picked by any token, then the expert table
constexpr int SMEM_PICKED_MASK_OFFSET =
    SMEM_TOPK_W_OFFSET + Config::MAX_NUM_TOKENS * Config::TOP_K * sizeof(float);
constexpr int SMEM_TABLE_OFFSET  = SMEM_PICKED_MASK_OFFSET + Config::NUM_EXPERTS / 8;
constexpr int SMEM_REDUCE_OFFSET = SMEM_TABLE_OFFSET + (sizeof(ExpertTable) + 15) / 16 * 16;

// a block's sync slot: sync (1)'s packets of {3 logits, epoch} from the first, sync (2)'s {epoch}
// at SYNC2_PACKET
constexpr int SYNC2_PACKET = 2;
static_assert(SYNC2_PACKET < PACKETS_PER_SLOT);

__device__ inline float sigmoid(float x) {
    return __builtin_amdgcn_rcpf(1.0f + __expf(-x));
}

// Copies an expert table; ids past count become -1.
__device__ inline void copy_table(ExpertTable *dst, const ExpertTable &src) {
    const int t = threadIdx.x;
    if (t < Config::MAX_SLOTS) {
        const int id = src.ids[t]; // read before the branch below, so both reads go out together
        store_data<float, 4>(dst->w[t], src.w[t]);
        dst->ids[t] = t < src.count ? id : -1;
    }
    if (t == 0) {
        dst->count = src.count;
    }
}

// gate_up: an item is 8 gate rows and the matching 8 up rows of one expert, one 16-row MFMA tile.
// Table slot r owns items 32r .. 32r + 31 and block b takes items b, b + 256, ...; the 4 waves
// split K, 12 blocks of 128 each.
constexpr int WAVE_K_BLOCKS    = Config::NUM_GROUPS / WAVES;
constexpr int ITEMS_PER_EXPERT = Config::INTERMEDIATE_SIZE / 8;
constexpr int MAX_ITEMS =
    (Config::MAX_SLOTS * ITEMS_PER_EXPERT + Config::NUM_BLOCKS - 1) / Config::NUM_BLOCKS;
// a 16-row group of preshuffled weights
constexpr int GROUP_BYTES = 16 * Config::HIDDEN_SIZE;
// LDS: each wave's 16x16 fp32 result per item [MAX_ITEMS][4][64 lanes][4], then the items' weight
// scales [MAX_ITEMS][gate, up][NUM_GROUPS] padded to whole rounds of threads, so every thread
// stores without a branch: the compiler moves the load that feeds such a store into the branch,
// after the weight loads, and then waits for all of them
constexpr int ITEM_SCALES = 2 * Config::NUM_GROUPS;
constexpr int SCALES_PER_THREAD =
    (MAX_ITEMS * ITEM_SCALES + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
constexpr int SMEM_SCALES_OFFSET = MAX_ITEMS * Config::BLOCK_SIZE * sizeof(floatx4);
constexpr int SMEM_GATE_UP_SIZE =
    SMEM_SCALES_OFFSET + SCALES_PER_THREAD * Config::BLOCK_SIZE * sizeof(float);

// This block's gate_up items, x, its scales and the table in LDS; smem takes the partial sums and
// (fp8) the items' weight scales. h goes out in 16 B sc1 stores, for blocks on other XCDs to read.
template <int NUM_TOKENS, bool MXFP4>
__device__ __forceinline__ void gate_up_block(const uint8_t *x_q, const uint8_t *x_s,
                                              const ExpertTable &table, const uint8_t *weight,
                                              const void *weight_scale, bfloat16 *h,
                                              uint8_t *smem) {
    constexpr int GROUP_STRIDE = MXFP4 ? GROUP_BYTES / 2 : GROUP_BYTES; // a 16-row group
    static_assert(WAVE_K_BLOCKS % 2 == 0); // MXFP4: two K blocks per e8m0 dword
    floatx4  *partials  = reinterpret_cast<floatx4 *>(smem);
    float    *scales    = reinterpret_cast<float *>(smem + SMEM_SCALES_OFFSET);
    const int tid       = threadIdx.x;
    const int lane      = tid % THREADS_PER_WARP;
    const int kb0       = tid / THREADS_PER_WARP * WAVE_K_BLOCKS;
    const int first     = blockIdx.x;
    const int count     = __builtin_amdgcn_readfirstlane(table.count);
    const int num_items = (count * ITEMS_PER_EXPERT - first + Config::NUM_BLOCKS - 1) /
                          Config::NUM_BLOCKS;
    // 256 is a multiple of 32: all of this block's items are the same chunk
    const int  chunk   = first % ITEMS_PER_EXPERT;
    const auto slot_of = [&](int n) {
        return min((first + n * Config::NUM_BLOCKS) / ITEMS_PER_EXPERT, Config::MAX_SLOTS - 1);
    };

    // everything but the weights first: global loads complete in issue order, so waiting for one
    // issued after the weights would wait for all of them. Past count, ids are 0.
    int experts[MAX_ITEMS];
#pragma unroll
    for (int n = 0; n < MAX_ITEMS; ++n) {
        experts[n] = __builtin_amdgcn_readfirstlane(table.ids[slot_of(n)]);
    }
    float item_scales[SCALES_PER_THREAD];
    if constexpr (!MXFP4) {
#pragma unroll
        for (int k = 0; k < SCALES_PER_THREAD; ++k) {
            const int i     = tid + k * Config::BLOCK_SIZE;
            const int n     = min(i / ITEM_SCALES, MAX_ITEMS - 1);
            const int block =
                table.ids[slot_of(n)] * 4 + i / Config::NUM_GROUPS % 2 * 2 + chunk / 16;
            item_scales[k]  = static_cast<const float *>(
                weight_scale)[block * Config::NUM_GROUPS + i % Config::NUM_GROUPS];
        }
    }
    // x is every item's B operand, with its scales (MXFP4: lane l's e8m0, of K 32 (l / 16) on);
    // columns past M repeat token M - 1 and are dropped
    const int token = min(lane % 16, NUM_TOKENS - 1);
    Fragment<MXFP4> x[WAVE_K_BLOCKS];
    std::conditional_t<MXFP4, int, float> x_scale[WAVE_K_BLOCKS];
#pragma unroll
    for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
        if constexpr (MXFP4) {
            x[j] = *reinterpret_cast<const int32x4 *>(x_q + token * Config::HIDDEN_SIZE / 2 +
                                                      (kb0 + j) * 64 + lane / 16 * 16);
            x_scale[j] = x_s[token * Config::HIDDEN_SIZE / 32 + (kb0 + j) * 4 + lane / 16];
        } else {
            const uint8_t *src =
                x_q + token * Config::HIDDEN_SIZE + (kb0 + j) * 128 + lane / 16 * 16;
            x[j]       = load_fragment(src, src + 64);
            x_scale[j] = reinterpret_cast<const float *>(x_s)[token * Config::NUM_GROUPS + kb0 + j];
        }
    }

    // lanes l % 16 < 8 take gate rows, the others the matching up rows; their results land in C
    // rows 0-7 (lanes 0-31) and 8-15 (lanes 32-63), (fp8) in different 128-row scale blocks
    const int  row      = 8 * (chunk % 2) + lane % 8; // of its 16-row group
    const auto group_of = [&](int n) {
        return experts[n] * 2 * Config::INTERMEDIATE_SIZE / 16 +
               (lane % 16 < 8 ? 0 : Config::INTERMEDIATE_SIZE / 16) + chunk / 2;
    };
    const auto weight_of = [&](int n) {
        return weight + static_cast<size_t>(group_of(n)) * GROUP_STRIDE +
               kb0 * K_BLOCK_BYTES_OF<MXFP4> + lane / 16 * 256 + row * 16;
    };
    // MXFP4: lane l's e8m0 of K blocks kb0 + 2p and kb0 + 2p + 1 share a dword, at bytes 0 and 2
    // once shifted right by `shift` (the row's half of its 32-row block)
    const int  shift     = chunk / 2 % 2 * 8;
    const auto scales_of = [&](int n) {
        return static_cast<const uint8_t *>(weight_scale) +
               e8m0_dword<Config::HIDDEN_SIZE / 32>(group_of(n) * 16 + row, 4 * kb0 + lane / 16);
    };
    // w[j] holds this wave's K block j of item n (MXFP4: w_e8m0[j / 2] its scales); with prefetch,
    // it loads the next item's as soon as its MFMA has read it
    Fragment<MXFP4> w[WAVE_K_BLOCKS];
    int        w_e8m0[WAVE_K_BLOCKS / 2];
    const auto load_w = [&](int j, int n) {
        const uint8_t *item = weight_of(n);
        if constexpr (MXFP4) {
            if (j % 2 == 0) {
                w_e8m0[j / 2] = *reinterpret_cast<const int *>(scales_of(n) + j / 2 * 256);
            }
            w[j] = __builtin_nontemporal_load(
                reinterpret_cast<const int32x4 *>(item + j * K_BLOCK_BYTES_OF<true>));
        } else {
            w[j] = load_fragment_nt(item + j * K_BLOCK_BYTES, item + j * K_BLOCK_BYTES + 1024);
        }
    };
#pragma unroll
    for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
        load_w(j, 0);
    }
    if constexpr (!MXFP4) {
#pragma unroll
        for (int k = 0; k < SCALES_PER_THREAD; ++k) {
            scales[tid + k * Config::BLOCK_SIZE] = item_scales[k];
        }
        block_sync_lds();
    }

    const auto item = [&](int n, auto prefetch) {
        floatx4 acc = {};
        if constexpr (MXFP4) { // the scales go into the instruction, which accumulates
#pragma unroll
            for (int p = 0; p < WAVE_K_BLOCKS / 2; ++p) {
                const int w_scale = w_e8m0[p] >> shift;
                acc = mfma_16x16x128_fp4<0, 0>(w[2 * p], x[2 * p], w_scale, x_scale[2 * p], acc);
                acc = mfma_16x16x128_fp4<2, 0>(w[2 * p + 1], x[2 * p + 1], w_scale,
                                               x_scale[2 * p + 1], acc);
                if constexpr (prefetch) {
                    load_w(2 * p, n + 1);
                    load_w(2 * p + 1, n + 1);
                }
            }
        } else {
            const float *w_scale =
                scales + n * ITEM_SCALES + (lane < 32 ? 0 : Config::NUM_GROUPS) + kb0;
#pragma unroll
            for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
                acc += mfma_16x16x128_fp8(w[j], x[j]) * (w_scale[j] * x_scale[j]);
                if constexpr (prefetch) {
                    load_w(j, n + 1);
                }
            }
        }
        partials[n * Config::BLOCK_SIZE + tid] = acc;
    };
    // straight-line code per item count, so the compiler can count the loads in flight exactly
    const auto run = [&](auto items) {
#pragma unroll
        for (int n = 0; n < items - 1; ++n) {
            item(n, std::true_type{});
        }
        item(items - 1, std::false_type{});
    };
    static_assert(MAX_ITEMS == 5);
    switch (num_items) {
    case 1: run(std::integral_constant<int, 1>{}); break;
    case 2: run(std::integral_constant<int, 2>{}); break;
    case 3: run(std::integral_constant<int, 3>{}); break;
    case 4: run(std::integral_constant<int, 4>{}); break;
    case 5: run(std::integral_constant<int, 5>{}); break;
    default: return;
    }
    __syncthreads();

    // thread (n, j, m): gate row j and up row j of token m in item n, summed over the 4 waves in
    // a fixed order; C row r of a wave's tile is at lane 16 (r / 4) + m, element r % 4
    if (tid < num_items * 8 * NUM_TOKENS) {
        const int      n    = tid / (8 * NUM_TOKENS);
        const int      j    = tid / NUM_TOKENS % 8;
        const int      m    = tid % NUM_TOKENS;
        const floatx4 *tile = partials + n * Config::BLOCK_SIZE + 16 * (j / 4) + m;
        float          gate = 0.0f;
        float          up   = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            gate += tile[v * THREADS_PER_WARP][j % 4];
            up += tile[v * THREADS_PER_WARP + 32][j % 4];
        }
        // HF: g and u are bf16 outputs of the linears
        reinterpret_cast<bfloat16 *>(scales)[tid] =
            silu_mul(static_cast<bfloat16>(gate), static_cast<bfloat16>(up));
    }
    // thread (n, m): token m's 8 values of item n, from the scales' LDS, now free
    block_sync_lds();
    if (tid < num_items * NUM_TOKENS) {
        const int   n   = tid / NUM_TOKENS;
        const int   m   = tid % NUM_TOKENS;
        const int   row = slot_of(n) * Config::MAX_NUM_TOKENS + m;
        const auto *v   = reinterpret_cast<const uint16_t *>(scales) + n * 8 * NUM_TOKENS + m;
        uint32x4    val;
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            val[j] = v[2 * j * NUM_TOKENS] |
                     static_cast<uint32_t>(v[(2 * j + 1) * NUM_TOKENS]) << 16;
        }
        store_sc1(reinterpret_cast<uint32x4 *>(h + row * Config::INTERMEDIATE_SIZE + 8 * chunk),
                  val);
    }
}

// down: every expert with the row split in all_reduce.h, wave w taking 128-K block w % 2 of
// its group; each wave keeps the next DOWN_DEPTH experts' weights in flight (MXFP4 too: 16 was
// 1.2 us slower at M = 4).
constexpr int DOWN_DEPTH       = 8;
// of which loaded before waiting for every block's h: more would queue ahead of the h reads
constexpr int DOWN_PRE         = 6;
constexpr int DOWN_GROUP_BYTES = 16 * Config::INTERMEDIATE_SIZE;
// h's 1x128 groups, (slot, token, K block) in MoeParams::act order
constexpr int H_GROUPS = Config::MAX_SLOTS * Config::MAX_NUM_TOKENS * 2;

template <bool MXFP4> struct DownSmem {
    uint8_t     h[H_GROUPS * 128]; // fp8
    float       coef[H_GROUPS];    // h's scale times the routing weight
    float       w_scale[Config::MAX_SLOTS][WAVES];
    RowsSmem    rows;
};
template <> struct DownSmem<true> {
    uint8_t  h[H_GROUPS * 64];     // MXFP4
    uint8_t  h_e8m0[H_GROUPS * 4]; // one per 32
    RowsSmem rows;
};
// The down of one block, table in LDS; call is the all-reduce's call number. publish() announces
// this block's h, the first DOWN_PRE experts' weights go out, then wait() for every block's h.
template <int NUM_TOKENS, bool MXFP4, typename Publish, typename Wait>
__device__ __forceinline__ void down_block(const DownParams &p, const ExpertTable &table,
                                           DownSmem<MXFP4> &s, uint32_t call, Publish publish,
                                           Wait wait) {
    constexpr int GROUP_STRIDE = MXFP4 ? DOWN_GROUP_BYTES / 2 : DOWN_GROUP_BYTES; // a 16-row group
    const int tid   = threadIdx.x;
    const int lane  = tid % THREADS_PER_WARP;
    const int wave  = tid / THREADS_PER_WARP;
    const int group = split_group(wave);
    const int row   = split_row(wave, lane);
    const int kb    = wave % 2;

    const int count = __builtin_amdgcn_readfirstlane(table.count);

    // h, 16 lanes per group; past count, the last group again
    constexpr int H_ITERS = (Config::MAX_SLOTS * NUM_TOKENS * 2 * 16 + Config::BLOCK_SIZE - 1) /
                            Config::BLOCK_SIZE;
    const auto    h_group = [&](int it) {
        const int g = min((tid + it * Config::BLOCK_SIZE) / 16, count * NUM_TOKENS * 2 - 1);
        return g / (NUM_TOKENS * 2) * Config::MAX_NUM_TOKENS * 2 + g % (NUM_TOKENS * 2);
    };
    // MXFP4: w_e8m0[d] holds lane l's e8m0 (of K 32 (l / 16) on in its tile) at byte 0 once
    // shifted right by `shift`
    const int  shift = (kb * 2 + group % 2) * 8;
    Fragment<MXFP4> w[DOWN_DEPTH];
    int             w_e8m0[DOWN_DEPTH];
    const auto load_w = [&](int d, int r) {
        const int      expert = __builtin_amdgcn_readfirstlane(table.ids[min(r, count - 1)]);
        const uint8_t *src    = p.weight +
                             (static_cast<size_t>(expert) * Config::HIDDEN_SIZE / 16 + group) *
                                 GROUP_STRIDE +
                             kb * K_BLOCK_BYTES_OF<MXFP4> + lane / 16 * 256 + row * 16;
        if constexpr (MXFP4) {
            // in the [experts' rows, INTERMEDIATE_SIZE / 32] e8m0
            const int scale_row = expert * Config::HIDDEN_SIZE + group * 16 + row;
            w_e8m0[d]           = *reinterpret_cast<const int *>(
                static_cast<const uint8_t *>(p.weight_scale) +
                e8m0_dword<Config::INTERMEDIATE_SIZE / 32>(scale_row, 4 * kb + lane / 16));
            w[d] = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(src));
        } else {
            w[d] = load_fragment_nt(src, src + 1024);
        }
    };
    // fp8: the weight scales before any other load (storing them waits for every load issued
    // earlier), a thread's for slot tid / WAVES (past count, the last again) and wave tid % WAVES
    const int scale_slot = min(tid / WAVES, count - 1);
    float     w_scale    = 0.0f;
    if constexpr (!MXFP4) {
        const int i =
            (table.ids[scale_slot] * Config::NUM_GROUPS + split_group(tid % WAVES) / 8) * 2 +
            tid % 2;
        w_scale = static_cast<const float *>(p.weight_scale)[i];
    }
    // the first weights stream while the other blocks finish gate_up
    publish();
#pragma unroll
    for (int d = 0; d < DOWN_PRE; ++d) {
        load_w(d, d);
    }
    wait();
    const float residual = all_reduce_residual<NUM_TOKENS>(p.ar);
    // written by other XCDs: sc1 loads, past this XCD's caches, 16 B each (8 B agent-scope atomics
    // take twice the loads and measured 0.3~0.7 us slower)
    const auto h_buffer = raw_buffer(p.h, sizeof(bfloat16) * H_GROUPS * 128);
    bfloat16   h_regs[H_ITERS][8];
#pragma unroll
    for (int it = 0; it < H_ITERS; ++it) {
        const uint32x4 val =
            buffer_load_sc1(h_buffer, (h_group(it) * 128 + tid % 16 * 8) * sizeof(bfloat16));
        __builtin_memcpy(h_regs[it], &val, 16);
    }
#pragma unroll
    for (int d = DOWN_PRE; d < DOWN_DEPTH; ++d) {
        load_w(d, d);
    }

    // unconditional: skipping the groups past count lets the compiler move their reads behind the
    // weights' and wait for all of them. Round 0's h (its DOWN_DEPTH experts) first, the rest while
    // round 1's weights stream in
    constexpr int FIRST_ITERS = DOWN_DEPTH * NUM_TOKENS * 2 * 16 / Config::BLOCK_SIZE;
    static_assert(FIRST_ITERS * Config::BLOCK_SIZE == DOWN_DEPTH * NUM_TOKENS * 2 * 16);
    float      h_scale[H_ITERS];
    int        h_e8m0[H_ITERS];
    const auto quant = [&](int first, int last) {
#pragma unroll
        for (int it = first; it < last; ++it) {
            if constexpr (MXFP4) {
                h_e8m0[it] = quant_mxfp4(h_regs[it], s.h + h_group(it) * 64 + tid % 16 * 4);
            } else {
                h_scale[it] = quant_fp8(h_regs[it], s.h + h_group(it) * 128 + tid % 16 * 8);
            }
        }
        // kept out of the loop above so that loop has no branches
        if constexpr (MXFP4) {
            if (tid % 4 == 0) {
#pragma unroll
                for (int it = first; it < last; ++it) {
                    s.h_e8m0[h_group(it) * 4 + tid % 16 / 4] = h_e8m0[it];
                }
            }
        } else if (tid % 16 == 0) {
#pragma unroll
            for (int it = first; it < last; ++it) {
                const int g = h_group(it);
                const int r = g / 2 / Config::MAX_NUM_TOKENS;
                s.coef[g]   = h_scale[it] * table.w[r][g / 2 % Config::MAX_NUM_TOKENS];
            }
        }
    };
    quant(0, FIRST_ITERS);
    if constexpr (!MXFP4) {
        s.w_scale[scale_slot][tid % WAVES] = w_scale;
    }
    block_sync_lds();

    // columns past M repeat token M - 1 and are dropped
    const int  token  = min(lane % 16, NUM_TOKENS - 1);
    floatx4    acc    = {};
    const auto expert = [&](int r, int d) {
        if (r < count) {
            const int g = (r * Config::MAX_NUM_TOKENS + token) * 2 + kb;
            // MXFP4: the scales go into the instruction, the routing weight onto its result
            if constexpr (MXFP4) {
                const int32x4 h = *reinterpret_cast<const int32x4 *>(s.h + g * 64 + lane / 16 * 16);
                acc += mfma_16x16x128_fp4(w[d], h, w_e8m0[d] >> shift,
                                          s.h_e8m0[g * 4 + lane / 16]) *
                       table.w[r][token];
            } else {
                const uint8_t *h = s.h + g * 128 + lane / 16 * 16;
                acc += mfma_16x16x128_fp8(w[d], load_fragment(h, h + 64)) *
                       (s.w_scale[r][wave] * s.coef[g]);
            }
        }
        // past count, the last expert's weights again: unused, but loading them keeps every
        // round's load count fixed for the compiler
        load_w(d, r + DOWN_DEPTH);
    };
#pragma unroll
    for (int d = 0; d < DOWN_DEPTH; ++d) {
        expert(d, d);
    }
    quant(FIRST_ITERS, H_ITERS);
    block_sync_lds();
    for (int r0 = DOWN_DEPTH; r0 < count; r0 += DOWN_DEPTH) {
#pragma unroll
        for (int d = 0; d < DOWN_DEPTH; ++d) {
            expert(r0 + d, d);
        }
    }

    all_reduce_rows<NUM_TOKENS>(p.ar, s.rows, acc, call, residual);
}

// gate_up's partial sums and scales, after the block reduce's scratch [WAVES][M]
constexpr int SMEM_GATE_UP_OFFSET =
    SMEM_REDUCE_OFFSET + WAVES * Config::MAX_NUM_TOKENS * sizeof(float);
static_assert(SMEM_GATE_UP_OFFSET % 16 == 0 &&
              SMEM_GATE_UP_OFFSET + SMEM_GATE_UP_SIZE <= Config::SMEM_SIZE);
// down's, after gate_up's
constexpr int SMEM_DOWN_OFFSET = (SMEM_GATE_UP_OFFSET + SMEM_GATE_UP_SIZE + 15) / 16 * 16;
static_assert(SMEM_DOWN_OFFSET + sizeof(DownSmem<false>) <= Config::SMEM_SIZE &&
              SMEM_DOWN_OFFSET + sizeof(DownSmem<true>) <= Config::SMEM_SIZE);

// What the MoE's start reads besides h, which a layer kernel loads ahead: gamma, block b's router
// row (expert b's) and lane l's router biases (experts 4l .. 4l + 3)
struct MoeFront {
    bfloat16 gamma[ROW_LOADS][8];
    bfloat16 router[ROW_LOADS][8];
    float    bias[Config::NUM_EXPERTS / THREADS_PER_WARP];
};
__device__ __forceinline__ void load_front(const MoeParams &p, MoeFront &f) {
    const int tid = threadIdx.x;
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, f.gamma[i]);
    }
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(
            p.router_weight + blockIdx.x * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8,
            f.router[i]);
    }
    load_data<float, 4>(p.router_bias + tid % THREADS_PER_WARP * 4, f.bias);
}

// The MoE layer's work on this block, at this call's epoch, last_call its all-reduce's last call
// number (as row_linear_ar_block's); MXFP4 as p.mxfp4. IN_LAYER, in a layer kernel: h was written
// earlier in the same kernel on other XCDs, so wait_h() first and read it through sc1 loads; the
// rest of the start (*front) is already loaded.
template <int NUM_TOKENS, bool MXFP4, bool DEBUG, bool RESIDUAL, bool IN_LAYER = false,
          typename Wait = void (*)()>
__device__ __forceinline__ void moe_block(const MoeParams &p, uint8_t *smem, uint32_t epoch,
                                          uint32_t last_call, Wait wait_h = [] {},
                                          const MoeFront *front = nullptr) {
    constexpr int HIDDEN_SIZE = Config::HIDDEN_SIZE;
    constexpr int BLOCK_SIZE  = Config::BLOCK_SIZE;

    const int bid = blockIdx.x;
    const int tid = threadIdx.x;

    uint32x4 *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4 *my_slot = slots + bid * PACKETS_PER_SLOT;
    if constexpr (IN_LAYER) {
        wait_h();
    }

    bfloat16 x_regs[NUM_TOKENS][ROW_LOADS][8];
    bfloat16 residual_regs[NUM_TOKENS][ROW_LOADS][8];
    MoeFront own;
    const MoeFront &f = IN_LAYER ? *front : own;
    const auto h_buffer = raw_buffer(p.h, NUM_TOKENS * HIDDEN_SIZE * sizeof(bfloat16));
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            const int offset = m * HIDDEN_SIZE + (i * BLOCK_SIZE + tid) * 8;
            if constexpr (IN_LAYER) {
                const uint32x4 val = buffer_load_sc1(h_buffer, offset * sizeof(bfloat16));
                __builtin_memcpy(x_regs[m][i], &val, 16);
            } else {
                load_data<bfloat16, 8>(p.h + offset, x_regs[m][i]);
            }
            if constexpr (RESIDUAL) {
                load_data<bfloat16, 8>(p.residual + offset, residual_regs[m][i]);
            }
        }
    }
    // block b computes the router logits of expert b
    static_assert(Config::NUM_BLOCKS == Config::NUM_EXPERTS);
    if constexpr (!IN_LAYER) {
        load_front(p, own);
    }
    const auto &gamma_regs  = f.gamma;
    const auto &router_regs = f.router;
    const auto &bias_regs   = f.bias;
    // for the top-k, lane l scores experts l*EXPERTS_PER_LANE onward
    constexpr int EXPERTS_PER_LANE = Config::NUM_EXPERTS / THREADS_PER_WARP;
    static_assert(EXPERTS_PER_LANE == 4);
    const int warp_id = tid / THREADS_PER_WARP;
    const int lane_id = tid % THREADS_PER_WARP;

    // block b writes its chunks of the sum
    static_assert(Config::NUM_BLOCKS == BLOCK_SIZE);
    if constexpr (RESIDUAL) {
        add_rows(x_regs, residual_regs);
        if (tid == bid) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < ROW_LOADS; ++i) {
                    store_data<bfloat16, 8>(p.residual_out + m * HIDDEN_SIZE +
                                                (i * BLOCK_SIZE + tid) * 8,
                                            x_regs[m][i]);
                }
            }
        }
    }

    rms_norm_sglang<NUM_TOKENS, ROW_LOADS, false>(
        x_regs, gamma_regs, p.epsilon, reinterpret_cast<float *>(smem + SMEM_REDUCE_OFFSET));

    // router as in HF: logits = F.linear(y.float(), W.float()), accumulated in fp32
    float router_logits[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        router_logits[m] = 0.0f;
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x_regs[m][i]);
            const auto *w2 = reinterpret_cast<const bfloat16x2 *>(router_regs[i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                router_logits[m] =
                    __builtin_amdgcn_fdot2_f32_bf16(x2[j], w2[j], router_logits[m], false);
            }
        }
    }
    BlockReduce<SumOp, BLOCK_SIZE>(router_logits,
                                   reinterpret_cast<float *>(smem + SMEM_REDUCE_OFFSET));

    // sync (1), publish: logits and epoch go out in one 16 B store, so a reader that sees the
    // epoch also sees the logits
    constexpr int NUM_PACKETS = (NUM_TOKENS + 2) / 3;
    static_assert(NUM_PACKETS <= SYNC2_PACKET);
    if (tid == 0) {
        float vals[3 * NUM_PACKETS] = {};
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            vals[m] = router_logits[m];
        }
#pragma unroll
        for (int k = 0; k < NUM_PACKETS; ++k) {
            const uint32x4 packet = {__float_as_uint(vals[3 * k]), __float_as_uint(vals[3 * k + 1]),
                                     __float_as_uint(vals[3 * k + 2]), epoch};
            store_sc1(my_slot + k, packet);
        }
    }

    // x quant for the expert GEMMs: fp8, a scale per 128, or MXFP4, an e8m0 per 32
    uint8_t *x_q = smem + SMEM_X_OFFSET;
    uint8_t *x_s = smem + SMEM_X_SCALE_OFFSET;
    quant_rows<NUM_TOKENS, ROW_LOADS, MXFP4>(x_regs, x_q, x_s);

    // zero the mask and the table: LDS starts with garbage, the top-k ORs its picks into the mask,
    // the grouping writes only the picked slots and the weights of tokens that picked them, and
    // gate_up reads scales for every slot it might take
    if (tid < (SMEM_REDUCE_OFFSET - SMEM_PICKED_MASK_OFFSET) / 16) {
        reinterpret_cast<uint32x4 *>(smem + SMEM_PICKED_MASK_OFFSET)[tid] = uint32x4{};
    }

    // sync (1), gather after the quant so other blocks have had time to publish: thread t waits
    // for block t's packets of this epoch
    float   *logits = reinterpret_cast<float *>(smem + SMEM_LOGITS_OFFSET);
    uint32x4 packets[NUM_PACKETS];
    do {
        load_sc1(slots + tid * PACKETS_PER_SLOT, packets);
    } while (packets[0][3] != epoch || packets[NUM_PACKETS - 1][3] != epoch);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        logits[m * Config::NUM_EXPERTS + tid] = __uint_as_float(packets[m / 3][m % 3]);
    }
    __syncthreads();

    // top-k as in HF noaux_tc (n_group = topk_group = 1): wave m picks token m's experts by
    // sigmoid(logit) + bias, one wave-wide max per pick; ties go to the lower expert id
    static_assert(Config::MAX_NUM_TOKENS <= WAVES);
    int      *topk_ids    = reinterpret_cast<int *>(smem + SMEM_TOPK_IDS_OFFSET);
    float    *topk_w      = reinterpret_cast<float *>(smem + SMEM_TOPK_W_OFFSET);
    uint32_t *picked_mask = reinterpret_cast<uint32_t *>(smem + SMEM_PICKED_MASK_OFFSET);
    if (warp_id < NUM_TOKENS) {
        const float *token_logits = logits + warp_id * Config::NUM_EXPERTS;
        // this lane's experts, sorted by key and then e, so a pick only compares the lanes' heads
        // and only the picked lane moves on; ties go to the lowest lane, so the lowest expert id
        uint32_t key[EXPERTS_PER_LANE];
        int      eid[EXPERTS_PER_LANE];
#pragma unroll
        for (int e = 0; e < EXPERTS_PER_LANE; ++e) {
            const float logit = token_logits[lane_id * EXPERTS_PER_LANE + e];
            key[e]            = ordered_bits(sigmoid(logit) + bias_regs[e]);
            eid[e]            = e;
        }
        const auto order = [&](int a, int b) {
            const bool     swap = key[b] > key[a] || (key[b] == key[a] && eid[b] < eid[a]);
            const uint32_t ka   = key[a];
            const int      ea   = eid[a];
            key[a]              = swap ? key[b] : ka;
            eid[a]              = swap ? eid[b] : ea;
            key[b]              = swap ? ka : key[b];
            eid[b]              = swap ? ea : eid[b];
        };
        static_assert(EXPERTS_PER_LANE == 4);
        order(0, 1);
        order(2, 3);
        order(0, 2);
        order(1, 3);
        order(1, 2);
        int ids[Config::TOP_K];
#pragma unroll
        for (int k = 0; k < Config::TOP_K; ++k) {
            const uint32_t best   = WarpReduce<MaxOp, uint32_t>(key[0]);
            const int      lane   = __builtin_ctzll(__ballot(key[0] == best));
            ids[k]                = lane * EXPERTS_PER_LANE + readlane(eid[0], lane);
            const bool     picked = lane_id == lane;
#pragma unroll
            for (int e = 0; e + 1 < EXPERTS_PER_LANE; ++e) {
                key[e] = picked ? key[e + 1] : key[e];
                eid[e] = picked ? eid[e + 1] : eid[e];
            }
            key[EXPERTS_PER_LANE - 1] = picked ? 0 : key[EXPERTS_PER_LANE - 1];
        }
        // weights as in HF: sigmoid without the bias, normalized, then scaled; lane k keeps pick k,
        // so the stores and the mask OR below are one LDS instruction each for all 8 picks
        int   pick_id    = 0;
        float pick_score = 0.0f;
        float sum        = 0.0f;
#pragma unroll
        for (int k = 0; k < Config::TOP_K; ++k) {
            const float score = sigmoid(token_logits[ids[k]]);
            sum += score;
            pick_id    = lane_id == k ? ids[k] : pick_id;
            pick_score = lane_id == k ? score : pick_score;
        }
        const float norm = __builtin_amdgcn_rcpf(sum + 1e-20f) * p.routed_scaling_factor;
        if (lane_id < Config::TOP_K) {
            topk_ids[warp_id * Config::TOP_K + lane_id] = pick_id;
            topk_w[warp_id * Config::TOP_K + lane_id]   = pick_score * norm;
            atomicOr(picked_mask + pick_id / 32, 1u << pick_id % 32);
        }
    }
    __syncthreads();

    // grouping for the expert GEMMs: the shared expert, then the picked ones in id order, so a
    // pick's slot is 1 + how many picked ids are below it
    ExpertTable &table = *reinterpret_cast<ExpertTable *>(smem + SMEM_TABLE_OFFSET);
    if (warp_id == 1 && lane_id < NUM_TOKENS * Config::TOP_K) {
        const int pick_id = topk_ids[lane_id];
        uint32_t mask[Config::NUM_EXPERTS / 32];
#pragma unroll
        for (int i = 0; i < Config::NUM_EXPERTS / 32; i += 4) {
            load_data<uint32_t, 4>(picked_mask + i, mask + i);
        }
        int rank  = 0;
        int count = 0;
#pragma unroll
        for (int i = 0; i < Config::NUM_EXPERTS / 32; ++i) {
            const int below = min(max(pick_id - 32 * i, 0), 32);
            rank += __popc(mask[i] & static_cast<uint32_t>((1ull << below) - 1));
            count += __popc(mask[i]);
        }
        table.ids[1 + rank]                        = pick_id;
        table.w[1 + rank][lane_id / Config::TOP_K] = topk_w[lane_id];
        table.ids[0]                               = Config::SHARED_EXPERT;
#pragma unroll
        for (int m = 0; m < Config::MAX_NUM_TOKENS; ++m) {
            table.w[0][m] = 1.0f;
        }
        table.count = 1 + count;
    }
    __syncthreads(); // the grouping
    if (!IN_LAYER && bid == 0) {
        copy_table(p.table, table); // for the moe op's caller
    }

    // debug output: every block writes the whole y and copies its LDS, so the test also checks
    // that blocks agree
    if constexpr (DEBUG) {
        bfloat16 *y_ptr = p.y_dbg + bid * NUM_TOKENS * HIDDEN_SIZE;
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                store_data<bfloat16, 8>(
                    y_ptr + m * HIDDEN_SIZE + (i * BLOCK_SIZE + tid) * 8, x_regs[m][i]);
            }
        }
        constexpr int Q_BYTES = NUM_TOKENS * HIDDEN_SIZE / (MXFP4 ? 2 : 1);
        constexpr int S_BYTES = NUM_TOKENS * HIDDEN_SIZE / 32; // either format
        uint8_t      *q_ptr   = p.q_dbg + bid * Q_BYTES;
        for (int c = tid * 16; c < Q_BYTES; c += BLOCK_SIZE * 16) {
            uint8_t chunk[16];
            load_data<uint8_t, 16>(x_q + c, chunk);
            store_data<uint8_t, 16>(q_ptr + c, chunk);
        }
        for (int k = tid; k < S_BYTES; k += BLOCK_SIZE) {
            p.s_dbg[bid * S_BYTES + k] = x_s[k];
        }
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            const int k = m * Config::NUM_EXPERTS + tid;
            p.logits_dbg[bid * NUM_TOKENS * Config::NUM_EXPERTS + k] = logits[k];
        }
        if (tid < NUM_TOKENS * Config::TOP_K) {
            p.ids_dbg[bid * NUM_TOKENS * Config::TOP_K + tid] = topk_ids[tid];
            p.w_dbg[bid * NUM_TOKENS * Config::TOP_K + tid]   = topk_w[tid];
        }
        copy_table(p.table_dbg + bid, table);
    }

    // gate_up: x, its scales and the table are already in this block's LDS
    gate_up_block<NUM_TOKENS, MXFP4>(x_q, x_s, table, p.gate_up_weight, p.gate_up_scale, p.act,
                                     smem + SMEM_GATE_UP_OFFSET);

    // sync (2), as (1) in the slot's SYNC2_PACKET: once every block's h is out, thread t waits for
    // block t's
    const auto publish_h = [&] { publish(my_slot + SYNC2_PACKET, epoch); };
    const auto wait      = [&] { wait_for(slots, SYNC2_PACKET, 0, Config::NUM_BLOCKS, epoch); };
    down_block<NUM_TOKENS, MXFP4>(p.down, table,
                                  *reinterpret_cast<DownSmem<MXFP4> *>(smem + SMEM_DOWN_OFFSET),
                                  last_call + 1u, publish_h, wait);
}

