#include "glm5/moe.h"

namespace infera_flash::glm5 {

template <int NUM_TOKENS, bool MXFP4, bool DEBUG, bool RESIDUAL>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
moe_mlp_kernel(const MoeParams p) {
    extern __shared__ __align__(16) uint8_t smem[];
    const uint32_t epoch = next_epoch(static_cast<const uint32x4 *>(p.workspace) +
                                      blockIdx.x * PACKETS_PER_SLOT);
    // the all-reduce's last call number, read now so no wait before the down includes it
    moe_block<NUM_TOKENS, MXFP4, DEBUG, RESIDUAL>(p, smem, epoch, last_call(p.down.ar));
}

void moe_launch(const MoeParams &params, int num_tokens, bool debug, hipStream_t stream) {
    using Kernel = void (*)(MoeParams);
#define MOE_KERNELS(MXFP4, DEBUG, RESIDUAL)                                                        \
    {moe_mlp_kernel<1, MXFP4, DEBUG, RESIDUAL>, moe_mlp_kernel<2, MXFP4, DEBUG, RESIDUAL>,                \
     moe_mlp_kernel<3, MXFP4, DEBUG, RESIDUAL>, moe_mlp_kernel<4, MXFP4, DEBUG, RESIDUAL>}
    // [mxfp4][debug][residual][M - 1]
    static const Kernel kernels[2][2][2][Config::MAX_NUM_TOKENS] = {
        {{MOE_KERNELS(false, false, false), MOE_KERNELS(false, false, true)},
         {MOE_KERNELS(false, true, false), MOE_KERNELS(false, true, true)}},
        {{MOE_KERNELS(true, false, false), MOE_KERNELS(true, false, true)},
         {MOE_KERNELS(true, true, false), MOE_KERNELS(true, true, true)}},
    };
#undef MOE_KERNELS
    const auto kernel = kernels[params.mxfp4][debug][params.residual != nullptr][num_tokens - 1];
    kernel<<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, Config::SMEM_SIZE, stream>>>(params);
    C10_HIP_CHECK(hipGetLastError());
}

