// GLM-5's decoder layer after its attention on one TP8 rank for M <= 4 tokens, fp8 experts at a
// scale per 128 x 128 block (GLM-5.3-FP8): the residual stream through post_attention_layernorm,
// the router's sigmoid top-8 in fp32, the shared expert in the last slot, the expert GEMMs on
// activations quantized per 1 x 128, then their output summed over the ranks of the peer memory in
// rank order and added to the stream: Infera-Flash's MoE kernel (glm5/moe.hip) on fp8 weights.
// source: Infera-Flash csrc/glm5 at 3b1dc45
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <optional>
#include <torch/library.h>

#include "glm5/moe.h"

